import java.io.*;
import java.net.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.json.*;

public class ReportExportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || !validateSession(sessionToken)) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String customFilter = req.getParameter("filter");
        String outputFormat = req.getParameter("format");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against allowed values
        if (!reportType.matches("^(sales|inventory|audit|compliance)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (!dateRange.matches("^\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}$")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        try {
            String results = executeReport(reportType, dateRange, customFilter);

            if ("csv".equals(outputFormat)) {
                resp.setContentType("text/csv");
                resp.setHeader("Content-Disposition", 
                    "attachment; filename=report_" + reportType + ".csv");
            } else {
                resp.setContentType("application/json");
            }
            resp.getWriter().write(results);

        } catch (SQLException e) {
            resp.sendError(500, "Report generation failed: " + e.getMessage());
        }
    }

    private String executeReport(String reportType, String dateRange, String customFilter)
            throws SQLException {

        String[] dates = dateRange.split("_");
        String startDate = dates[0];
        String endDate = dates[1];

        String baseQuery = "SELECT * FROM reports_" + reportType + 
            " WHERE created_at BETWEEN '" + startDate + "' AND '" + endDate + "'";

        // Apply optional custom filter - allows flexible reporting
        if (customFilter != null && !customFilter.isEmpty()) {
            // Basic sanitization: remove comments and semicolons
            String sanitized = customFilter.replaceAll("--", "")
                                          .replaceAll(";", "")
                                          .replaceAll("/\\*.*?\\*/", "");
            baseQuery += " AND " + sanitized;
        }

        Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
        Statement stmt = conn.createStatement();
        ResultSet rs = stmt.executeQuery(baseQuery);

        JSONArray results = new JSONArray();
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();

        while (rs.next()) {
            JSONObject row = new JSONObject();
            for (int i = 1; i <= cols; i++) {
                row.put(meta.getColumnName(i), rs.getObject(i));
            }
            results.put(row);
        }

        rs.close();
        stmt.close();
        conn.close();

        return results.toString();
    }

    private boolean validateSession(String token) {
        try {
            Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            PreparedStatement ps = conn.prepareStatement(
                "SELECT 1 FROM active_sessions WHERE token = ? AND expires_at > NOW()");
            ps.setString(1, token);
            ResultSet rs = ps.executeQuery();
            boolean valid = rs.next();
            rs.close();
            ps.close();
            conn.close();
            return valid;
        } catch (SQLException e) {
            return false;
        }
    }
}
